type Props = Omit<SVGProps<SVGSVGElement>, 'children'> & {
  name: ToolIconName;
  size?: number;
};

export function ToolIcon({ name, size = 16, ...props }: Props) {
  const { paths, evenOdd, viewBox = '0 0 24 24' } = marks[name];

  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="currentColor"
      fillRule={evenOdd ? 'evenodd' : undefined}
      aria-hidden="true"
      {...props}
    >
      {paths.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
}
